SELECT g.*, c.name as category_name, COALESCE(sales.total_quantity, 0) as sales_count FROM goods g LEFT JOIN category c ON g.category_id = c.id LEFT JOIN ( SELECT oi.goods_id, SUM(oi.quantity) as total_quantity FROM order_item oi JOIN `order` o ON oi.order_id = o.id WHERE o.status = 'completed' GROUP BY oi.goods_id ) sales ON sales.goods_id = g.id WHERE g.is_deleted = 0
AND g.category_id IN
#{id}
AND g.category_id = #{categoryId}
AND (g.name LIKE CONCAT('%', #{keyword}, '%') OR g.bar_code LIKE CONCAT('%', #{keyword}, '%'))
AND g.is_on_sale = #{isOnSale}
ORDER BY
COALESCE(sales.total_quantity, 0) DESC, g.created_at DESC
g.price ASC, g.created_at DESC
g.price DESC, g.created_at DESC
g.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM goods g WHERE g.is_deleted = 0


